export async function pay(cents: number, token: string, headers: Record<string, string>) {
  const res = await fetch("https://api.stripe.com/v1/charges", {
    method: "POST",
    headers,
    body: JSON.stringify({ amount_cents: cents, currency: "usd", source: token }),
  });
  return res.json();
}

