export async function pay(cents: number, token: string, headers: Record<string, string>) {
  const res = await fetch("https://api.stripe.com/v1/payment_intents", {
    method: "POST",
    headers,
    body: JSON.stringify({ pricing: { unit_amount: cents }, currency: "usd", payment_method: token, confirm: true }),
  });
  return res.json();
}
